"use client";

import "../../styles/teum-base.css";
import "../../styles/components/textarea.css";
import { useId, useState, type ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export type TextareaProps = ComponentPropsWithRef<"textarea"> & {
  label?: string;
  description?: string;
  error?: string;
  showCount?: boolean;
};

export function Textarea({ id: providedId, label, description, error, showCount, maxLength, className, value, defaultValue, onChange, ref, ...props }: TextareaProps) {
  const generatedId = useId();
  const id = providedId ?? generatedId;
  const descriptionId = description ? `${id}-description` : undefined;
  const errorId = error ? `${id}-error` : undefined;
  const describedBy = [props["aria-describedby"], descriptionId, errorId].filter(Boolean).join(" ") || undefined;
  const initialValue = value ?? defaultValue ?? "";
  const [uncontrolledCount, setUncontrolledCount] = useState(typeof initialValue === "string" ? initialValue.length : 0);
  const count = typeof value === "string" ? value.length : uncontrolledCount;

  return (
    <div className="teum-field teum-textarea-field" data-invalid={Boolean(error) || undefined}>
      {label && <label className="teum-field__label" htmlFor={id}>{label}</label>}
      <textarea
        ref={ref}
        id={id}
        className={cn("teum-input teum-textarea", className)}
        aria-invalid={Boolean(error) || undefined}
        aria-describedby={describedBy}
        maxLength={maxLength}
        value={value}
        defaultValue={defaultValue}
        onChange={(event) => { setUncontrolledCount(event.currentTarget.value.length); onChange?.(event); }}
        {...props}
      />
      <div className="teum-textarea-field__meta">
        <span>
          {description && <span id={descriptionId} className="teum-field__description">{description}</span>}
          {error && <span id={errorId} className="teum-field__error">{error}</span>}
        </span>
        {showCount && maxLength && <output aria-label="Character count">{count}/{maxLength}</output>}
      </div>
    </div>
  );
}

/* Generated from src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-textarea {
  min-height: 96px;
  resize: vertical;
  padding: 9px 10px;
  line-height: 1.5;
}

.teum-textarea-field__meta { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }

.teum-textarea-field__meta > span { min-width: 0; }

.teum-textarea-field__meta output { flex: 0 0 auto; color: var(--teum-ink-tertiary); font-size: var(--teum-type-metadata); font-variant-numeric: tabular-nums; }

.teum-field { display: grid; min-width: 0; gap: 6px; }

.teum-field__label { color: var(--teum-ink); font-size: 12px; font-weight: 550; }

.teum-field[data-invalid] .teum-field__control { border-color: color-mix(in oklch, var(--teum-fg-danger) 46%, var(--teum-control-border)); box-shadow: 0 0 0 2px color-mix(in oklch, var(--teum-fg-danger) 11%, transparent); }

.teum-input { width: 100%; min-width: 0; height: 100%; padding: 0 9px; border: 0; outline: 0; background: transparent; color: var(--teum-ink); font-size: 13.5px; }

.teum-input::placeholder { color: var(--teum-fg-subtle); }

.teum-input:disabled { background: var(--teum-bg-subtle); color: var(--teum-fg-disabled); cursor: not-allowed; }

.teum-input:read-only { color: var(--teum-fg-muted); }

.teum-field__description,
.teum-field__error { color: var(--teum-ink-tertiary); font-size: 11.5px; line-height: 1.45; }

.teum-field__error { color: var(--teum-fg-danger); font-weight: 520; }

:root[data-theme="dark"] .teum-input:disabled { background: rgb(255 255 255 / 0.025); color: var(--teum-ink-disabled); }
}
